#!/usr/bin/env python3
"""Search all captured byte dumps this session for any direct branch/call to 0x120381c0."""
import capstone

dumps = {
    0x12038180: "a34d05005b09feff714d0500510dfeffd74c05008d0bfeffa54c05001c4e0500014e0500b34d0500aa4d0500a54d05000c4c0500d74d0500e24d0500de4d0500f0b503af2de9000fadf5a04d91b08246d6481e4615467844d0f80080d8f8000047f8240c03f09cf988b14ff00009d8f8000057f8241c884201bf48460df5a04d",
    0x12038200: "",
    0x1203b520: "",
    0x1203a760: "",
    0x1203a7d4: "",
    0x12025230: "",
    0x12025484: "",
    0x120375fc: "",
    0x12037488: "",
    0x1203b684: "",
    0x1203b6f8: "",
}

md = capstone.Cs(capstone.CS_ARCH_ARM, capstone.CS_MODE_THUMB)
found = []
for base, hexstr in dumps.items():
    data = bytes.fromhex(hexstr)
    for insn in md.disasm(data, base):
        if insn.mnemonic in ('bl', 'blx', 'b', 'b.w', 'beq', 'beq.w', 'bne', 'bne.w'):
            op = insn.op_str
            if op.startswith('#0x'):
                try:
                    target = int(op[1:], 16)
                    if target in (0x120381c0, 0x120381c1):
                        found.append((hex(base), hex(insn.address), insn.mnemonic, insn.op_str))
                except Exception:
                    pass

print("Direct branches/calls to 0x120381c0 found in already-captured bytes:")
for f in found:
    print(f)
if not found:
    print("NONE FOUND in captured dumps.")
